// Normalizacao do payload + chave de idempotencia determinística
// Roda uma vez para todos os itens recebidos no webhook.
const crypto = require('crypto');
const sha256 = (v) => crypto.createHash('sha256').update(String(v)).digest('hex');

// Cache de chaves já processadas (persiste entre execuções do workflow).
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.chaves)) store.chaves = [];
const LIMITE_CACHE = 5000;

const saida = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  const canal = String(b.canal || '').trim().toLowerCase();
  const remetente = String(b.remetente || '').trim();
  const texto = String(b.texto || '').trim();
  const idExterno = b.id_evento ? String(b.id_evento) : null;
  const recebidoEm = new Date().toISOString();
  const tsOrigem = b.timestamp ? String(b.timestamp) : recebidoEm;

  // Validacao dos campos obrigatorios
  const faltando = [];
  if (!canal) faltando.push('canal');
  if (!remetente) faltando.push('remetente');
  if (!texto) faltando.push('texto');

  // Chave de idempotencia: id do evento quando existe, senao chave derivada estavel
  const chave = idExterno
    ? sha256(canal + ':' + idExterno)
    : sha256(canal + ':' + remetente + ':' + tsOrigem.slice(0, 16) + ':' + sha256(texto));

  let status = 'novo';
  let motivo = null;

  if (faltando.length) {
    status = 'invalido';
    motivo = 'campos obrigatorios ausentes: ' + faltando.join(', ');
  } else if (store.chaves.includes(chave)) {
    status = 'duplicado';
    motivo = 'chave de idempotencia ja processada';
  } else {
    store.chaves.push(chave);
    if (store.chaves.length > LIMITE_CACHE) {
      store.chaves = store.chaves.slice(-LIMITE_CACHE);
    }
  }

  saida.push({
    json: {
      chave,
      canal,
      remetente,
      texto,
      id_externo: idExterno,
      timestamp_origem: tsOrigem,
      recebido_em: recebidoEm,
      status,
      motivo,
      tentativas: 0,
      http_status: null,
      ultimo_erro: null,
      na_fila_reprocessamento: false,
      payload_original: b,
    },
  });
}

return saida;

// Classifica a resposta do CRM sem lancar excecao.
// 2xx  -> entregue
// 4xx  -> invalido (falha permanente, nao faz retry)
// resto -> retentar (falha transitoria)
const saida = [];

for (const item of $input.all()) {
  const base = $('Normalizacao e idempotencia').first().json;
  const anterior = item.json.__evento || base;
  const code = Number(item.json.statusCode || 0);
  const corpo = item.json.body;

  const evento = { ...anterior };
  evento.http_status = code;

  if (code >= 200 && code < 300) {
    evento.status = 'entregue';
    evento.motivo = null;
    evento.ultimo_erro = null;
  } else if (code >= 400 && code < 500) {
    evento.status = 'invalido';
    evento.motivo = 'CRM rejeitou o evento (' + code + '): falha permanente, sem retry';
    evento.ultimo_erro = typeof corpo === 'string' ? corpo.slice(0, 500) : JSON.stringify(corpo || {}).slice(0, 500);
  } else {
    evento.status = 'retentar';
    evento.tentativas = Number(anterior.tentativas || 0) + 1;
    evento.motivo = 'falha transitoria no CRM (' + (code || 'sem resposta') + ')';
    evento.ultimo_erro = typeof corpo === 'string' ? corpo.slice(0, 500) : JSON.stringify(corpo || {}).slice(0, 500);
  }

  saida.push({ json: evento });
}

return saida;

// Fecha o ciclo de vida do evento com um status final explicito.
// Nenhum evento sai daqui sem desfecho.
const FINAIS = ['entregue', 'duplicado', 'invalido', 'falha'];

return $input.all().map((item) => {
  const e = { ...item.json };

  if (e.status === 'retentar') {
    e.status = 'falha';
    e.na_fila_reprocessamento = true;
    e.motivo = 'tentativas de entrega esgotadas (' + e.tentativas + '/3): ' + (e.motivo || '');
  }

  if (!FINAIS.includes(e.status)) {
    e.status = 'falha';
    e.na_fila_reprocessamento = true;
    e.motivo = 'status inesperado ao final do fluxo';
  }

  e.finalizado_em = new Date().toISOString();
  return { json: e };
});

// Monta a mensagem de alerta: canal, chave, status e ultimo erro.
// Enxuto de proposito: quem recebe precisa decidir sem abrir o n8n.
return $input.all().map((item) => {
  const e = item.json;
  const linhas = [
    '[PONTE DE EVENTOS] ' + String(e.status).toUpperCase(),
    'canal: ' + e.canal,
    'remetente: ' + e.remetente,
    'chave: ' + e.chave,
    'tentativas: ' + e.tentativas,
    'http: ' + (e.http_status === null ? '-' : e.http_status),
    'motivo: ' + (e.motivo || '-'),
    'erro: ' + (e.ultimo_erro || '-'),
    'fila de reprocessamento: ' + (e.na_fila_reprocessamento ? 'sim' : 'nao'),
  ];
  return { json: { alerta: linhas.join('\n'), evento: e } };
});
